"""Independent Python reference model of PROTOCOL.md v3.0 (development cross-check only)."""
import copy, hashlib, struct
M62 = (1 << 62) - 1
M60 = 1 << 60
LV = ['I', 'H', 'A']
EMPTY = hashlib.sha256(b'').hexdigest()

class Err(Exception):
    def __init__(self, code, off=0):
        self.code = code; self.off = off

def e(c):
    raise Err(c)

# ---------------- varints ----------------
def rvar(b, i, need_min=False, trunc='FRAME_ENCODING_ERROR'):
    if i >= len(b): e(trunc)
    w = 1 << (b[i] >> 6)
    if i + w > len(b): e(trunc)
    v = b[i] & 0x3f
    for k in range(1, w): v = (v << 8) | b[i + k]
    if need_min and w != minw(v): e(trunc)
    return v, i + w

def minw(v):
    return 1 if v < 64 else 2 if v < 16384 else 4 if v < (1 << 30) else 8

def enc(v):
    w = minw(v)
    return (([1, 2, 4, 8].index(w) << (8 * w - 2)) | v).to_bytes(w, 'big')

def rbe(b, i, n):
    if i + n > len(b): e('FRAME_ENCODING_ERROR')
    return int.from_bytes(b[i:i + n], 'big'), i + n

def reconstruct(raw, width, expected):
    m = 1 << (8 * width); half = m >> 1
    d = (raw - expected) % m
    n0 = expected + d
    if d > half and n0 - m >= 0: return n0 - m
    return n0

# ---------------- interval utilities ----------------
def merge(list_, a, b):
    """merge half-open [a,b) into sorted disjoint non-adjacent list"""
    if b <= a: return list_
    rest = [iv for iv in list_ if iv[1] < a or iv[0] > b]
    lo, hi = a, b
    again = True
    while again:
        again = False
        for s, en in rest:
            if en >= lo and s <= hi and not (s > hi and en < lo):
                if en >= lo and s <= hi and (s <= hi and en >= lo):
                    if s <= hi and en >= lo and (en >= lo and s <= hi):
                        if (s <= hi and en >= lo) and (s <= hi and en >= lo):
                            pass
                # adjacent or overlapping
                if s <= hi and en >= lo:
                    lo = min(lo, s); hi = max(hi, en); rest.remove((s, en)); again = True
                    break
    out = sorted(rest + [(lo, hi)])
    return out

def card(list_):
    return sum(en - s for s, en in list_)

def prefix_of(list_):
    for s, en in list_:
        if s == 0: return en
    return 0

def ledger_hash(list_):
    return hashlib.sha256(b''.join(struct.pack('>QQ', s, en) for s, en in list_)).hexdigest()

def bytes_ranges(store):
    """store: dict pos->byte -> merged half-open intervals"""
    if not store: return []
    out = []
    for pos in sorted(store):
        if out and out[-1][1] == pos: out[-1][1] = pos + 1
        else: out.append([pos, pos + 1])
    return [(s, en) for s, en in out]

def bytes_insert(store, off, data):
    """returns (newstore, ok)"""
    new = dict(store)
    for k in range(len(data)):
        pos = off + k
        if pos in new and new[pos] != data[k]:
            return None, False
    for k in range(len(data)):
        new[off + k] = data[k]
    return new, True

# ---------------- header framing ----------------
def parse_header(wire, pos, cidw):
    """returns dict or None for BAD_HEADER"""
    bad = {'bad': True}
    b = wire
    first = b[pos]
    if first & 0x80:
        base = first & 0xfc
        if base not in (0xc0, 0xe0): return bad
        lvl = 0 if base == 0xc0 else 1
        width = (first & 3) + 1
        i = pos + 1
        if i + 4 > len(b): return bad
        if b[i:i + 4] != b'\x00\x00\x00\x01': return bad
        i += 4
        if i + 1 > len(b): return bad
        dl = b[i]; i += 1
        if dl > 20: return bad
        if i + dl > len(b): return bad
        dcid = b[i:i + dl]; i += dl
        if i + 1 > len(b): return bad
        sl = b[i]; i += 1
        if sl > 20: return bad
        if i + sl > len(b): return bad
        scid = b[i:i + sl]; i += sl
        token = b''
        if lvl == 0:
            try:
                tl, i = rvar(b, i, False, 'BAD')
            except Err:
                return bad
            if tl > len(b) - i: return bad
            token = b[i:i + tl]; i += tl
        try:
            length, i = rvar(b, i, False, 'BAD')
        except Err:
            return bad
        if length < width: return bad
        if i + length > len(b): return bad
        raw, j = rbe(b, i, width)
        payload = b[i + width:i + length]
        return {'bad': False, 'lvl': lvl, 'width': width, 'raw': raw, 'dcid': dcid, 'scid': scid,
                'token': token, 'payload': payload, 'end': i + length, 'phase': 0}
    if (first & 0xc0) != 0x40 or (first & 0x18) != 0: return bad
    width = (first & 3) + 1
    phase = (first >> 2) & 1
    i = pos + 1
    if i + cidw + width > len(b): return bad
    dcid = b[i:i + cidw]; i += cidw
    raw, i = int.from_bytes(b[i:i + width], 'big'), i + width
    return {'bad': False, 'lvl': 2, 'width': width, 'raw': raw, 'dcid': dcid, 'scid': b'',
            'token': b'', 'payload': b[i:], 'end': len(b), 'phase': phase}

# ---------------- the audit ----------------
def audit(trace):
    st = {
        'keys': {'I'}, 'largest': [None, None, None], 'seen': [set(), set(), set()],
        'epochs': {}, 'current': 0, 'closed': False,
        'streams': {}, 'crypto': [{}, {}, {}], 'ack': [[], [], []], 'ecn': [[0, 0, 0], [0, 0, 0], [0, 0, 0]],
        'peer_obs': {0: (trace['peer']['cid'], trace['peer']['token'])},
        'owner': {trace['peer']['cid']: 0}, 'active': {0}, 'threshold': 0,
        'retired': [], 'opened': [0, 0], 'used': 0, 'smd': 0, 'sms': [0, 0],
    }
    lim = trace['limits']; loc = trace['local']
    cfg = {'lim': lim, 'loc': loc, 'cids': [bytes.fromhex(x) for x in loc['cids']]}
    for idx, level in enumerate(LV):
        seed = trace['received'][level]
        if seed is not None:
            st['largest'][idx] = seed
            st['seen'][idx].add(seed)
            if level == 'A': st['epochs'][0] = [seed, seed, 1]
    rows = []; drows = []; closed_row = None
    for event, ev in enumerate(trace['events']):
        if 'keys' in ev:
            if not st['closed']: st['keys'] = set(ev['keys'])
            continue
        wire = bytes.fromhex(ev['datagram']['wire']); auth = ev['datagram']['auth']
        pos = 0; attempts = 0; accepted = 0; accbytes = b''
        while pos < len(wire):
            p = parse_header(wire, pos, len(cfg['cids'][0]))
            p['event'] = event; p['index'] = attempts; attempts += 1
            ann = auth[p['index']] if p['index'] < len(auth) else None
            acc, closed_row = packet(st, cfg, p, ann, rows)
            if p['bad']: break
            if acc:
                accepted += 1; accbytes += acc
            pos = p['end']
        drows.append({'event': event, 'packets': attempts, 'accepted': accepted,
                      'bytes': len(accbytes), 'sha256': hashlib.sha256(accbytes).hexdigest()})
    return output(st, cfg, rows, drows, closed_row)

def row(p, level, pn, epoch, status, sha):
    return {'event': p['event'], 'packet': p['index'], 'offset': p['offset'] if 'offset' in p else 0,
            'level': level, 'pn': pn, 'epoch': epoch, 'status': status, 'sha256': sha}

def packet(st, cfg, p, ann, rows):
    if p['bad']:
        p['offset'] = 0
        rows.append(row(p, None, None, None, 'BAD_HEADER', None))
        return None, None
    p['offset'] = p['offset'] if 'offset' in p else 0
    lvl = p['lvl']
    expected = (st['largest'][lvl] + 1) if st['largest'][lvl] is not None else 0
    pn = reconstruct(p['raw'], p['width'], expected)
    st_ = st
    if st['closed']:
        rows.append(row(p, LV[lvl], pn, None, 'CLOSED', None)); return None, None
    dest = None
    for i, c in enumerate(cfg['cids']):
        if c == p['dcid']: dest = i
    if dest is None or in_ranges(st['retired'], dest):
        rows.append(row(p, LV[lvl], pn, None, 'DROP_CID', None)); return None, None
    if LV[lvl] not in st['keys']:
        rows.append(row(p, LV[lvl], pn, None, 'NO_KEY', None)); return None, None
    if pn > M62:
        rows.append(row(p, LV[lvl], pn, None, 'PN_RANGE', None)); return None, None
    gen = None
    if lvl == 2:
        if ann is None or ann > M62 or not gen_ok(st, ann, p['phase']):
            rows.append(row(p, LV[lvl], pn, None, 'AUTH', None)); return None, None
        gen = ann
    else:
        if ann != 0:
            rows.append(row(p, LV[lvl], pn, None, 'AUTH', None)); return None, None
    epoch_out = gen if lvl == 2 else None
    if pn in st['seen'][lvl]:
        rows.append(row(p, LV[lvl], pn, epoch_out, 'DUPLICATE', None)); return None, None
    if lvl == 2 and not order_ok(st, gen, pn):
        rows.append(row(p, LV[lvl], pn, epoch_out, 'KEY_UPDATE_ERROR', None))
        st['closed'] = True
        return None, {'event': p['event'], 'packet': p['index'], 'offset': 0, 'code': 'KEY_UPDATE_ERROR'}
    work = copy.deepcopy(st)
    work['closed'] = st['closed']
    try:
        payload, close = frames(work, cfg, p, lvl, dest)
        if lvl == 2: accept_epoch(work, gen, pn)
        work['seen'][lvl].add(pn)
        if work['largest'][lvl] is None or pn > work['largest'][lvl]: work['largest'][lvl] = pn
        st.clear(); st.update(work)
        envelope = canonical(p, payload, expected)
        if close is not None:
            st['closed'] = True
            closed_row = {'event': p['event'], 'packet': p['index'], 'offset': close[0], 'code': 'PEER_CLOSE'}
            rows.append(row(p, LV[lvl], pn, epoch_out, 'PEER_CLOSE', hashlib.sha256(envelope).hexdigest()))
        else:
            closed_row = None
            rows.append(row(p, LV[lvl], pn, epoch_out, 'OK', hashlib.sha256(envelope).hexdigest()))
        return envelope, closed_row
    except Err as error:
        rows.append(row(p, LV[lvl], pn, epoch_out, error.code, None))
        st['closed'] = True
        return None, {'event': p['event'], 'packet': p['index'], 'offset': error.off, 'code': error.code}

def in_ranges(list_, value):
    return any(s <= value < en for s, en in list_)

def gen_ok(st, g, phase):
    if (g & 1) != phase: return False
    cur = st['current']
    return g == cur or (g == cur - 1 and cur >= 1) or (g == cur + 1 and cur < M62)

def order_ok(st, g, pn):
    for other, stats in st['epochs'].items():
        if other == g: continue
        if g > other:
            if pn <= stats[1]: return False
        else:
            if pn >= stats[0]: return False
    return True

def accept_epoch(st, g, pn):
    if g == st['current'] + 1: st['current'] = g
    if g not in st['epochs']: st['epochs'][g] = [pn, pn, 1]
    else:
        s = st['epochs'][g]
        s[0] = min(s[0], pn); s[1] = max(s[1], pn); s[2] += 1

# ---------------- canonical ----------------
def canonical(p, payload, expected):
    out = bytearray()
    width = 4
    for cand in (1, 2, 3, 4):
        if reconstruct(p['pn'] & ((1 << (8 * cand)) - 1), cand, expected) == p['pn']:
            width = cand; break
    pn = p['pn']
    if p['lvl'] != 2:
        out.append((0xc0 if p['lvl'] == 0 else 0xe0) | (width - 1))
        out += b'\x00\x00\x00\x01'
        out.append(len(p['dcid'])); out += p['dcid']
        out.append(len(p['scid'])); out += p['scid']
        if p['lvl'] == 0:
            out += enc(len(p['token'])); out += p['token']
        out += enc(width + len(payload))
        out += (pn & ((1 << (8 * width)) - 1)).to_bytes(width, 'big')
        out += payload
    else:
        out.append(0x40 | (p['phase'] << 2) | (width - 1))
        out += p['dcid']
        out += (pn & ((1 << (8 * width)) - 1)).to_bytes(width, 'big')
        out += payload
    return bytes(out)
